        // Set up owner and user
        address owner = address(this);
        address user = address(0x1234);

        // Fund user with Ether
        vm.deal(user, 1 ether);

        // User calls getTokens() to receive tokens and become blacklisted
        vm.prank(user);
        c.getTokens{value: 0}();

        // Owner burns some of user's tokens (to change totalDistributed, but user has at least 1000e18 tokens)
        vm.prank(owner);
        // First ensure owner has enough tokens (from XBornID) - but owner already has totalDistributed
        // Actually, the constructor XBornID() is never called; we need to call it manually
        // But in this test, we can just burn from owner's balance which is 0 initially.
        // Let's adjust: we'll just check the receive() divergence directly.

        // Instead, let's use a simpler divergence: after user calls getTokens(), the reference version's 
        // receive() function calls getTokens() which updates value and sends tokens, but the buggy version's 
        // receive() does nothing. So we compare the user's balance after sending Ether via receive().

        // First, let's reset and do a clean scenario:
        // Owner sends some Ether to contract via receive() — reference calls getTokens() which may revert if totalRemaining=0 or distribution finished.
        // But the buggy version's receive() does nothing, so Ether stays in contract.

        // Let's do: user sends Ether to contract via receive(). The reference updates state (if possible), the buggy does not.
        // We'll see that after the call, the contract's Ether balance is different.

        vm.deal(user, 1 ether);
        // Ensure distribution is not finished and totalRemaining > 0
        // The initial totalRemaining = 300000000e18, value = 1000e18, so it's fine.

        vm.prank(user);
        (bool success, ) = address(c).call{value: 1 ether}("");

